import React, { useState } from "react";

// PenRunner — Prototipo "Le mie iscrizioni" (scuderia)
// Regola del contesto: lo stato di ogni binomio mostra ciò che la scuderia
// vuole sapere ADESSO (ordine di partenza, diretta, risultato) — mai codici.
// Avvisi umani con l'azione di chi li può risolvere. Azioni di riga on-hover.
// Toggle Desktop/Mobile in alto per collaudare i due layout.

const COVER_TAPPA = "data:image/png;base64,";
const COVER_LIVE = "data:image/jpeg;base64,";
const COVER_PAST = "data:image/jpeg;base64,";

const C = {
  accent: "#15803D", accent500: "#16A34A", accent50: "#DCFCE7",
  ink: "#0F172A", ink900: "#0B1120", darkPanel: "#141C2E",
  slate700: "#334155", slate500: "#64748B", slate400: "#94A3B8",
  slate300: "#CBD5E1", slate100: "#F1F5F9", slate50: "#F8FAFC", white: "#FFFFFF",
  warning: "#B45309", warnBg: "#FEF3C7", danger: "#B91C1C", live: "#DC2626", gold: "#C8902F",
};
const num = { fontVariantNumeric: "tabular-nums" };

/* ————— dati d'esempio ————— */
const EVENTI = [
  {
    id: "live", nome: "Censimento Show 5", date: "oggi", luogo: "Cremona", cover: COVER_LIVE, coverType: "photo",
    stato: "live",
    // ordine d'attenzione: in campo → deve correre → run completate
    binomi: [
      { cavallo: "Smart Dunit", cavaliere: "De Marchi Giulia", classe: "Rookie · L1 L2", pagata: "80 €",
        stato: { tipo: "campo", testo: "In campo ora", sub: "Rookie · pattern 9" } },
      { cavallo: "Chics Magic Whiz", cavaliere: "Ferrari Sofia", classe: "Rookie · L1", pagata: "40 €",
        stato: { tipo: "prossimo", testo: "Parte 9ª · stimata ~11:40", sub: "tra 5 binomi · ritmo attuale 4 min a run" } },
      { cavallo: "Gun Smoke Whiz", cavaliere: "Rossi Martina", classe: "Rookie · L1 L2", pagata: "80 €",
        stato: { tipo: "score", testo: "70,0 · 2ª provvisoria in L1", sub: "run completata · 4ª in L2" } },
    ],
  },
  {
    id: "tappa", nome: "Lombardia Reining · 3ª tappa", date: "12–14 settembre", luogo: "Cremona Fiera", cover: COVER_TAPPA, coverType: "logo",
    stato: "in-arrivo",
    binomi: [
      { cavallo: "Gunners Dream", cavaliere: "Ferrari Sofia", classe: "Open · L2 L3 (base L2)", pagata: "150 €",
        stato: { tipo: "draw", testo: "Parte 4ª su 14", sub: "sabato mattina · dopo il binomio 3" } },
      { cavallo: "Chocowhiz", cavaliere: "De Rossi Marco", classe: "Green · L1", pagata: "40 €",
        stato: { tipo: "attesa", testo: "Draw in preparazione", sub: "iscrizioni chiuse ieri" },
        avviso: { testo: "Patente FISE di Marco De Rossi in scadenza il 5 settembre", azione: "Completa il profilo" } },
      { cavallo: "Lil Ruf Peppy", cavaliere: "Moretti Elena", classe: "Youth 14-18", pagata: "in attesa · 30 €",
        stato: { tipo: "attesa", testo: "Iscrizione da completare", sub: "manca il pagamento" },
        avviso: { testo: "Il pagamento non risulta: senza saldo l'iscrizione decade alla chiusura", azione: "Paga ora · 30 €" } },
    ],
  },
  {
    id: "past", nome: "Estate Reining Show", date: "20–22 giugno", luogo: "Manerbio", cover: COVER_PAST, coverType: "photo",
    stato: "conclusa",
    binomi: [
      { cavallo: "Gunners Dream", cavaliere: "Ferrari Sofia", classe: "Open · L2 L3", pagata: "150 €",
        stato: { tipo: "risultato", testo: "L2: 3ª · 218,5", sub: "L3: 6ª — premio 240 €" } },
      { cavallo: "Smart Dunit", cavaliere: "De Marchi Giulia", classe: "Rookie · L1", pagata: "40 €",
        stato: { tipo: "risultato", testo: "L1: 1ª · 221,0", sub: "campionessa di classe" } },
    ],
  },
];

/* ————— pezzi ————— */
function useLogoBg() { return "#FFFFFF"; } // nel prodotto: colore campionato all'upload

function CoverThumb({ src, type, w = 84, h = 48 }) {
  const bg = useLogoBg();
  return (
    <div style={{ width: w, height: h, borderRadius: 6, flexShrink: 0, position: "relative", overflow: "hidden", background: type === "logo" ? bg : C.darkPanel }}>
      {type === "logo"
        ? <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}><img src={src} alt="" style={{ maxWidth: "78%", maxHeight: "76%" }} /></div>
        : <img src={src} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />}
    </div>
  );
}

function Stato({ s }) {
  if (s.tipo === "campo") return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 6, color: C.live, fontWeight: 700, fontSize: 13.5 }}>
        <span style={{ width: 8, height: 8, borderRadius: 99, background: C.live }} /> {s.testo}
      </div>
      <div style={{ fontSize: 12, color: C.slate500 }}>{s.sub}</div>
    </div>
  );
  const colori = { score: C.ink, draw: C.ink, attesa: C.slate500, risultato: C.ink, prossimo: C.accent };
  const peso = { score: 700, draw: 700, attesa: 500, risultato: 700, prossimo: 800 };
  return (
    <div>
      <div style={{ fontSize: 13.5, fontWeight: peso[s.tipo], color: colori[s.tipo], ...num }}>{s.testo}</div>
      <div style={{ fontSize: 12, color: C.slate500, ...num }}>{s.sub}</div>
    </div>
  );
}

function RigaBinomio({ b, mobile, evLive }) {
  const [hov, setHov] = useState(false);
  const [conf, setConf] = useState(false);
  return (
    <div onMouseEnter={() => setHov(true)} onMouseLeave={() => { setHov(false); setConf(false); }}
      style={{ borderTop: `1px solid ${C.slate100}`, background: hov ? C.slate50 : "transparent", padding: mobile ? "10px 14px" : "10px 16px" }}>
      <div style={{ display: "flex", alignItems: mobile ? "flex-start" : "center", gap: 12, flexDirection: mobile ? "column" : "row" }}>
        <div style={{ flex: mobile ? "unset" : "1 1 240px", minWidth: 0, opacity: evLive && b.stato.tipo === "score" ? 0.72 : 1 }}>
          <div style={{ fontSize: 14, fontWeight: 700 }}>{b.cavallo} <span style={{ color: C.slate500, fontWeight: 400 }}>· {b.cavaliere}</span></div>
          <div style={{ fontSize: 12, color: C.slate500 }}>{b.classe}</div>
        </div>
        <div style={{ flex: mobile ? "unset" : "1 1 220px" }}><Stato s={b.stato} /></div>
        {!mobile && !evLive && (
          <div style={{ width: 120, textAlign: "right" }}>
            {conf ? (
              <span>
                <button onClick={() => setConf(false)} style={{ background: C.danger, color: C.white, border: "none", borderRadius: 6, padding: "4px 9px", fontSize: 11.5, fontWeight: 700, cursor: "pointer", marginRight: 4 }}>Sì, ritira</button>
                <button onClick={() => setConf(false)} style={{ background: C.white, border: `1px solid ${C.slate300}`, borderRadius: 6, padding: "4px 9px", fontSize: 11.5, cursor: "pointer", color: C.slate700 }}>No</button>
              </span>
            ) : (
              <button onClick={() => setConf(true)} style={{ opacity: hov ? 1 : 0, transition: "opacity .12s", background: "none", border: "none", color: C.danger, fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>Ritira</button>
            )}
          </div>
        )}
      </div>
      {b.avviso && (
        <div style={{ marginTop: 8, background: C.warnBg, borderRadius: 8, padding: "8px 12px", display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontSize: 12.5, color: "#7C4A03", flex: "1 1 240px" }}>{b.avviso.testo}</span>
          <button style={{ background: C.accent, color: C.white, border: "none", borderRadius: 6, padding: "6px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>{b.avviso.azione}</button>
        </div>
      )}
    </div>
  );
}

function CardEvento({ ev, mobile }) {
  const live = ev.stato === "live";
  return (
    <section style={{ background: C.white, border: `1px solid ${C.slate300}`, borderRadius: 12, overflow: "hidden", marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: mobile ? "12px 14px" : "12px 16px", background: live ? C.ink900 : C.white, color: live ? C.white : C.ink }}>
        <CoverThumb src={ev.cover} type={ev.coverType} w={mobile ? 64 : 84} h={mobile ? 38 : 48} />
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 15, fontWeight: 800, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{ev.nome}</div>
          <div style={{ fontSize: 12, color: live ? C.slate400 : C.slate500 }}>{ev.date} · {ev.luogo}</div>
        </div>
        <div style={{ marginLeft: "auto", flexShrink: 0 }}>
          {live
            ? <a style={{ color: "#FCA5A5", fontSize: 12.5, fontWeight: 700, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6 }}><span style={{ width: 8, height: 8, borderRadius: 99, background: C.live }} />Risultati live</a>
            : <a style={{ color: C.accent, fontSize: 12.5, fontWeight: 600, cursor: "pointer" }}>{ev.stato === "conclusa" ? "Documenti" : "Pagina evento"}</a>}
        </div>
      </div>
      {ev.binomi.map((b, i) => <RigaBinomio key={i} b={b} mobile={mobile} evLive={live} />)}
    </section>
  );
}

/* ————— pagina ————— */
export default function MieIscrizioni() {
  const [mobile, setMobile] = useState(false);
  const inCorsa = EVENTI.filter((e) => e.stato === "live");
  const inArrivo = EVENTI.filter((e) => e.stato === "in-arrivo");
  const concluse = EVENTI.filter((e) => e.stato === "conclusa");
  const Sez = ({ titolo, colore }) => (
    <div style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: 1, color: colore || C.slate500, margin: "18px 0 8px", fontWeight: 700 }}>{titolo}</div>
  );
  return (
    <div style={{ minHeight: "100vh", background: C.slate50, color: C.ink, fontFamily: "-apple-system, 'Segoe UI', Roboto, sans-serif" }}>
      <div style={{ background: C.ink, color: C.white, padding: "12px 20px", display: "flex", alignItems: "center", gap: 12 }}>
        <strong style={{ fontSize: 15 }}>PenRunner — Scuderia</strong>
        <span style={{ color: C.slate400, fontSize: 12.5 }}>Scuderia 23QH</span>
        <span style={{ marginLeft: "auto", display: "flex", gap: 4, background: "#1E293B", borderRadius: 8, padding: 3 }}>
          {["Desktop", "Mobile"].map((m, i) => (
            <button key={m} onClick={() => setMobile(i === 1)} style={{
              border: "none", borderRadius: 6, padding: "4px 10px", fontSize: 11.5, fontWeight: 600, cursor: "pointer",
              background: mobile === (i === 1) ? C.accent : "transparent", color: C.white,
            }}>{m}</button>
          ))}
        </span>
      </div>

      <div style={{ maxWidth: mobile ? 390 : 900, margin: "0 auto", padding: mobile ? "14px 10px 60px" : "22px 24px 64px" }}>
        <h1 style={{ fontSize: mobile ? 20 : 24, margin: 0, letterSpacing: -0.3 }}>Le mie iscrizioni</h1>

        {inCorsa.length > 0 && <><Sez titolo="● In corsa adesso" colore={C.live} />{inCorsa.map((e) => <CardEvento key={e.id} ev={e} mobile={mobile} />)}</>}
        <Sez titolo="In arrivo" />
        {inArrivo.map((e) => <CardEvento key={e.id} ev={e} mobile={mobile} />)}
        <Sez titolo="Concluse" />
        {concluse.map((e) => <CardEvento key={e.id} ev={e} mobile={mobile} />)}

        <p style={{ marginTop: 18, fontSize: 12, color: C.slate400 }}>
          Prototipo di design — prova il toggle Desktop/Mobile in alto. Foto segnaposto, licenze da regolarizzare.
        </p>
      </div>
    </div>
  );
}
